import{_ as i,l as o,o as e,c as s,v as t,p as n,x as l,d as h,i as d,S as m}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"Krusell–Smith","description":"","frontmatter":{"title":"Krusell–Smith","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/krusell-smith.md","filePath":"econ/krusell-smith.md","lastUpdated":1789023840000}'),p={name:"econ/krusell-smith.md"};function u(_,a,c,K,E,S){const r=o("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="krusell–smith" tabindex="-1">Krusell–Smith <a class="header-anchor" href="#krusell–smith" aria-label="Permalink to &quot;Krusell–Smith&quot;">​</a></h1><div class="epigraph"><p>家庭若只用资本均值（加总量冲击）预报价格，而预报误差几乎为零，无限维分布就可以被有界理性的低维状态代替。</p><footer>—— Krusell and Smith, Income and Wealth Heterogeneity in the Macroeconomy, JPE 1998</footer></div><p><a href="/econ/bewley-aiyagari">上一课</a>的不变分布在确定性总量里闭合。一旦有总量 \\(Z_t\\)，真实状态含整个 \\(\\mu_t\\)，贝尔曼的自变量无限维。本课缺口是 <strong>Krusell–Smith 近似</strong>：用少数矩当预报充分统计。不重写 Aiyagari 稳态算法。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>价格 \\(r_t,w_t\\) 依赖资本总量与冲击，而资本总量是 \\(\\mu_t\\) 的积分。家庭要预报 \\(\\mu_{t+1}\\)。KS：假设家庭相信 \\(\\log K&#39;=\\alpha(Z)+\\beta(Z)\\log K\\)，只条件于今天的 \\(K\\) 与 \\(Z\\)，用模拟路径对这条定律做回归，更新信念直到自洽。若 \\(R^2\\) 极高，更高矩几乎不帮预报价格。缺口是给「分布是状态」一条可算的有界感知，而不是声称分布真的是一维。</p><p><span class="marginnote">Krusell and Smith, <em>JPE</em> 106(5), 1998, 867–896。后续：Den Haan–Rendahl 等改进模拟；Reiter 的投影把分布线性化。序列空间方法是另一条路。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>外层：总量定律。内层：个人 \\((a,z,K,Z)\\) 上的贝尔曼（比 Aiyagari 多两个总量状态）。模拟一大群家庭，得 \\(\\{K_t\\}\\)，再估定律。检查：把分布的其它矩加入预报，看是否改进 \\(r\\) 的预测。劳动供给、资本利用可同样处理。精度高不表示福利或分配效应可由 \\(K\\) 概括——预报价格与概括福利是两件事。</p>',8)),(e(),n(m,null,{default:l(()=>[d(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20BEL%5B%22%E4%BF%A1%E5%BF%B5%3A%20K'%20%3D%20f(K%2CZ)%22%5D%20--%3E%20V%5B%22%E5%AE%B6%E5%BA%AD%20V(a%2Cz%2CK%2CZ)%22%5D%0A%20%20V%20--%3E%20SIM%5B%22%E6%A8%A1%E6%8B%9F%E5%88%86%E5%B8%83%22%5D%0A%20%20SIM%20--%3E%20REG%5B%22%E5%9B%9E%E5%BD%92%E6%9B%B4%E6%96%B0%20f%22%5D%0A%20%20REG%20--%3E%20BEL%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[h(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>与一阶 HANK：对总量冲击线性化时，分布沿确定性稳态的偏离是无限维线性系统，可用缩减或序列空间解，不必 KS 的非线性模拟。KS 仍是非线性、大冲击的基准故事。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是价格对分布的依赖几乎是通过均值（在他们的校准里）。原因：资本供给来自几乎不受约束的富人，他们接近线性政策；约束家庭的资产少，不驱动 \\(K\\)。因此总量 IRF 可以接近代表性 RBC，而分配 IRF 完全不同。这解释了「加总矩看不出异质」与「政策的分配效应很大」可以并存。</p><p>若价格依赖谁持有资产（例如抵押、住房、名义债），均值不够，KS 的 \\(R^2\\) 会掉——后课债务与 HANK 会碰到。</p><p><span class="marginnote">有界感知是求解装置，不是宣布家庭真的不做更高阶推断。太阳黑子与学习是预期单元。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 NK 粘性接上（HANK）。不讨论帕累托尾是否破坏低维预报。算法细节（模拟多少人、如何插值）不是理论。不要把 KS 写成「异质无关」：它说的是<strong>预报价格</strong>时均值够用，不是福利或 MPC。</p><p>后课默认：有总量冲击的不完全市场，可用 KS 或线性化分布求解；加总接近代表并不取消分配。下一课：稳态财富的右尾为何比 Aiyagari 更厚。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>KS：用 \\(K\\) 与 \\(Z\\) 预报价格，自洽时 \\(R^2\\) 可极高。</li><li>总量 IRF 可像代表模型，分配效应仍在。</li><li>价格若依赖更高矩，近似失败。</li><li>出处：Krusell and Smith, <em>JPE</em> 1998。</li></ul>',10))])}const B=i(p,[["render",u]]);export{f as __pageData,B as default};
